add('air-fryer-fishcakes','Thai salmon cakes with chilli mayo',S,6,180,20,20,[[250,'g','skinless salmon','Cut into chunks'],[15,'ml','Thai red curry paste'],[1,'each','coriander handful','Chopped'],[7.5,'ml','fish sauce'],[1,'each','lime','Half for fish mixture, half for mayo'],[1,'each','lemongrass stalk','Tender core, chopped'],[3,'each','spring onions','Chopped'],[1,'each','egg'],[75,'ml','plain flour'],[50,'g','green beans','Finely chopped'],[75,'g','panko breadcrumbs'],[30,'ml','sriracha'],[75,'ml','mayonnaise']],['Pulse salmon, curry paste, coriander, fish sauce, half the lime juice, lemongrass, spring onion and egg until finely chopped.','Fold in flour and green beans. Shape six small, even patties, chill for 30 minutes, then coat with panko.','Air fry in one layer at 180°C for 15–20 minutes, turning gently halfway. Mix mayonnaise with sriracha and remaining lime juice and serve beside the cakes.'],preheat=3,wait=30,internal=75,allergens=['fish','egg','wheat','gluten','crustacean'],oilFree=True,equipment=['Food processor'],nutritionNote='Source per-serving estimate includes the sriracha mayonnaise. Thai curry paste may contain shrimp; check the jar. The egg-containing cakes are cooked to 75°C.')
add('air-fryer-pork-in-blanket-turnovers','Bacon sausage and chutney turnovers',M,12,200,15,12,[[320,'g','puff pastry','One ready-rolled sheet'],[45,'ml','red onion chutney'],[12,'each','bacon-wrapped cocktail sausages','Uncooked'],[50,'g','cheddar','Finely grated'],[1,'each','egg','Beaten']],['Cut pastry into 12 equal squares. Divide chutney and cheese between them, then place one bacon-wrapped sausage diagonally on each square.','Fold opposite pastry corners over the sausage and seal with beaten egg. Brush the exposed pastry with egg.','Air fry with gaps at 200°C for 10–12 minutes per batch. Continue if needed until the pastry is golden and sausage centres reach 71°C.'],preheat=3,internal=71,oilFree=True,allergens=['wheat','gluten','milk','egg','sulphites'],portion='One turnover; nutrition is per one of 12.',nutritionNote='Source estimate per turnover. Cocktail-sausage and pastry sizes vary; source allows 45–60 ml chutney, and this uses 45 ml.')
add('air-fryer-roast-dinner','Chicken breast roast dinner for two',Q,2,190,10,45,[[3,'each','medium potatoes','Peeled and quartered'],[3,'tsp','olive oil'],[2,'each','small skin-on chicken breasts'],[3,'each','carrots','Peeled and cut into batons'],[100,'g','peas','','frozen'],[30,'ml','water']],['Soak potatoes in cold water for 30 minutes; drain and dry. Toss with 1 tsp oil and air fry at 190°C for 10 minutes.','Oil the chicken with another teaspoon. Move potatoes aside, add chicken and cook for 10 minutes.','Toss carrots with remaining oil and add around the chicken. Cook for 10–15 minutes more. Remove chicken only once it reaches 74°C and rest it under a loose cover.','Put peas and water into an approved covered ramekin. Place beside the vegetables and cook for 10 minutes, until peas are hot and potatoes and carrots tender.'],preheat=2,wait=30,internal=74,equipment=['Air-fryer-safe covered ramekin'],nutritionNote='Publisher estimate uses 2–3 medium potatoes and one large or two small skin-on breasts; this selects three potatoes and two small breasts. Gravy is excluded.')
add('air-fryer-fish-chips','Crisp white fish and chunky chips',S,2,200,15,32,[[60,'g','cornflour'],[1,'tsp','smoked paprika'],[.5,'tsp','mixed herbs','','dried'],[2,'each','white fish fillets','Boneless; similar thickness'],[3,'each','medium potatoes','Cut into 1 cm chips'],[90,'ml','vegetable oil','30 ml chips; up to 60 ml fish coating']],['Mix cornflour, paprika and herbs, then coat both sides of the fish.','Toss chips with 30 ml oil. Air fry at 200°C for 18–22 minutes, shaking halfway, until tender and crisp. Keep warm.','Put the remaining oil on a plate and turn the coated fish through it. Air fry in one layer at 200°C for 8–10 minutes, turning carefully halfway, until 63°C in the centre.'],allergens=['fish'],nutritionNote='Publisher estimate for two portions uses 6–8 UK tablespoons oil and variable-size fish. This lists 6 tablespoons (90 ml); some dredging oil remains on the plate. Optional peas and tartare sauce excluded.')
add('air-fryer-sesame-prawn-toast','Sesame prawn toast triangles',S,16,180,15,10,[[165,'g','raw king prawns','Peeled and deveined'],[2,'each','garlic cloves'],[2,'each','spring onions','One chopped, one sliced'],[1,'tsp','ginger','Grated'],[1,'each','egg white'],[2,'tsp','soy sauce'],[1,'tsp','honey'],[4,'each','white bread slices'],[2,'tsp','sesame oil'],[15,'ml','sesame seeds']],['Pulse prawns, garlic, chopped spring onion, ginger, egg white, soy and honey into a paste. Keep refrigerated while preparing the bread.','Brush one side of each bread slice with sesame oil. Air fry at 180°C for 2–3 minutes to lightly toast, in batches as required.','Spread the raw prawn paste evenly over the toasts, add sesame seeds and cut each slice into four triangles.','Air fry the triangles in one layer for 3–5 minutes, checking the thickest topping reaches 75°C. Scatter with sliced spring onion.'],preheat=3,internal=75,allergens=['crustacean','egg','soy','wheat','gluten','sesame'],equipment=['Food processor'],portion='One of 16 small toast triangles; several make a snack.',nutritionNote='Published estimate per small toast triangle. Original permits 16 or 32 triangles and does not expose a clear yield; this fixes 16. Treat per-piece values as approximate. Unmeasured chive garnish omitted.')
add('air-fryer-pork-potato-kofte','Pork and potato kofte with bulgur salad',Q,4,190,20,18,[[500,'g','pork mince'],[250,'g','red potato','Coarsely grated'],[1,'each','red onion','Grated'],[2,'each','garlic cloves','Grated'],[1,'tsp','cumin seeds'],[2,'tsp','smoked paprika'],[1,'tsp','chilli flakes'],[25,'g','parsley','Finely chopped'],[150,'g','bulgur wheat','','dried'],[15,'ml','olive oil'],[1,'each','lemon','Cut into six wedges'],[.5,'each','cucumber','Diced'],[4,'each','tomatoes','Chopped'],[30,'ml','mint','Chopped','fresh'],[200,'g','hummus']],['Cover bulgur with 300 ml boiling water and leave until softened, following the packet.','Combine pork, grated potato, onion, garlic, cumin, paprika, chilli and parsley. Shape into eight firm, even fingers about 2 cm thick.','Air fry at 190°C for 15–18 minutes, turning halfway, until the centres reach 71°C.','Toss bulgur with olive oil, juice from two lemon wedges, cucumber, tomatoes and mint. Serve each portion with two kofte, hummus and remaining lemon.'],preheat=3,internal=71,allergens=['wheat','gluten','sesame'],nutritionNote='Publisher estimate includes a 200 g tub chosen from whipped feta, tzatziki or hummus; this selects hummus, so exact macros vary. Optional unmeasured oil spray omitted. Bulgur is weighed dry.')
add('air-fryer-sticky-chicken-with-crispy-potatoes','Sticky chicken thighs and crisp potato cubes',Q,2,190,10,23,[[22.5,'ml','olive oil','15 ml glaze; 7.5 ml potatoes'],[2,'tsp','honey'],[1,'tsp','soy sauce'],[1,'tsp','smoked paprika'],[4,'each','chicken thighs','Similar size'],[350,'g','potatoes','Cut into 1.5 cm cubes'],[.5,'tsp','mixed herbs','','dried']],['Combine 15 ml oil with honey, soy and paprika. Brush over chicken and air fry at 190°C for 8 minutes.','Meanwhile simmer potatoes in water for 5 minutes. Drain thoroughly, then toss with remaining oil and herbs.','Add potatoes around the chicken in a single layer. Air fry another 15 minutes, turning halfway, until potatoes are crisp and chicken reaches 74°C.'],preheat=3,internal=74,allergens=['soy','wheat','gluten'],equipment=['Saucepan'],nutritionNote='Source estimate for two thighs and half the potatoes. Source does not specify thigh weight or skin status; actual values vary. Optional salad excluded.')
add('air-fryer-scotch-eggs','Sage and bacon Scotch eggs',M,4,200,20,28,[[5,'each','eggs','Four whole; one for coating'],[350,'g','pork sausagemeat'],[6,'each','streaky bacon rashers','Finely chopped'],[8,'each','sage leaves','Chopped'],[1,'tsp','mixed herbs','','dried'],[40,'g','plain flour'],[75,'g','panko breadcrumbs']],['Air fry four whole eggs at 180°C for 8 minutes, then chill in ice water and peel carefully.','Mix sausagemeat, bacon and herbs. Divide into four discs, wrap each around a peeled egg and seal completely.','Roll each parcel in flour, dip in the remaining beaten egg and coat with panko.','Air fry at 200°C for about 20 minutes until golden. Probe the meat layer for 71°C and ensure the egg centre is hot and firm.'],internal=75,allergens=['egg','wheat','gluten','sulphites'],oilFree=True,nutritionNote='Publisher estimate per Scotch egg; source allows 50–75 g panko, here 75 g. Oil spray and optional mustard are omitted.')
add('air-fryer-harissa-sausage-veg-traybake','Harissa sausages with squash and kale',Q,2,200,10,45,[[1,'each','small butternut pumpkin','Deseeded and cut into 2 cm chunks'],[22.5,'ml','canola oil'],[1,'each','red capsicum','Cut into chunks'],[1,'each','red onion','Cut into wedges'],[4,'each','garlic cloves','Lightly crushed'],[4,'each','pork sausages'],[30,'ml','harissa paste'],[1,'each','lemon','Juice only'],[100,'g','kale','Tough stems removed; sliced']],['Toss pumpkin with 15 ml oil. Air fry at 200°C for 10 minutes.','Coat capsicum, onion and garlic with remaining oil. Add to pumpkin, shake and cook for 15 minutes.','Toss sausages with harissa and lemon juice. Add to the vegetables and cook 15 minutes, turning halfway.','Mix in kale and cook 5 minutes more. Check sausages reach 71°C and vegetables are tender.'],preheat=3,internal=71,allergens=['wheat','gluten','sulphites'],nutritionNote='Source permits 4–6 sausages and 30–45 ml harissa; listed recipe uses lower ends. Pumpkin and sausage size vary. Optional yoghurt is excluded.')
add('air-fryer-cheese-chorizo-quesadillas','Chorizo and cheddar quesadillas',Q,4,180,10,20,[[250,'g','cheddar','Grated'],[2,'each','tomatoes','Finely chopped'],[150,'g','chorizo','Ready-to-eat; finely chopped','cured'],[.5,'each','parsley bunch','Chopped'],[1,'each','red chilli','Chopped'],[6,'each','spring onions','Sliced'],[1,'each','lime','Juiced'],[8,'each','large flour tortillas']],['Mix cheddar, tomatoes, chorizo, parsley, chilli, spring onions and lime juice. Divide over one half of each tortilla, leaving a margin at the edge.','Fold each tortilla over and press closed. Use an approved air-fryer rack if needed to keep the tops from lifting; never add an unsuitable loose utensil.','Air fry in a single layer at 180°C for about 10 minutes per batch, turning at 5 minutes, until crisp and hot inside. Allow two batches for the listed time.'],preheat=3,internal=75,allergens=['milk','wheat','gluten','sulphites'],oilFree=True,portion='Two folded tortillas, one quarter of the batch.',nutritionNote='Publisher estimate says eight large tortillas for four portions; tortilla brands and sizes vary widely. Listed six spring onions chooses lower end of source range.')
add('air-fryer-mediterranean-style-chicken-bowl','Chicken and giant couscous bowls',Q,4,190,15,25,[[500,'g','boneless skinless chicken thighs','Halved'],[125,'g','Greek yoghurt'],[2,'tsp','mint','','dried'],[2,'each','garlic cloves','Grated'],[2,'tsp','turmeric'],[60,'ml','olive oil','30 ml chicken; 15 ml onions; 15 ml couscous'],[2,'tsp','ground coriander'],[2,'each','red onions','Sliced'],[200,'g','wholewheat giant couscous','','dried'],[1,'each','cucumber','Chopped'],[2,'each','large tomatoes','Chopped'],[10,'g','dill','Chopped'],[15,'ml','white wine vinegar']],['Coat chicken in yoghurt, mint, garlic, half the turmeric and coriander, and 30 ml oil.','Toss onions with 15 ml oil and remaining spices. Spread in the basket or approved shallow tray, then lay chicken over them without crowding. Air fry at 190°C for 20–25 minutes, turning halfway.','Cook couscous as directed on the packet. Toss cucumber, tomatoes and dill with vinegar.','Once chicken reaches 74°C, stir the roasted onions and remaining oil into couscous. Divide everything between four bowls.'],internal=74,allergens=['milk','wheat','gluten','sulphites'],equipment=['Saucepan'],nutritionNote='Source estimate includes 60 ml olive oil and 200 g dry couscous. Additional serving oil or yoghurt is excluded.')
add('air-fryer-kung-pao-style-peanut-prawns','Kung pao prawns and rice',Q,2,200,10,10,[[200,'g','raw king prawns','Peeled, deveined and thawed'],[1,'each','red capsicum','Cut into bite-size pieces'],[3,'each','spring onions','White parts chopped; greens sliced'],[1,'tsp','vegetable oil'],[30,'g','roasted peanuts','Chopped'],[30,'ml','soy sauce'],[30,'ml','hoisin sauce'],[2,'tsp','malt vinegar'],[1,'tsp','sesame oil'],[1,'tsp','cornflour'],[2,'tsp','honey'],[.5,'tsp','chilli flakes'],[250,'g','microwave rice','','cooked']],['Toss prawns, capsicum and onion whites with vegetable oil. Spread in an approved shallow air-fryer tray if the basket holes are large. Cook at 200°C for 6–8 minutes, shaking halfway, until prawns reach 63°C.','Whisk soy, hoisin, vinegar, sesame oil, cornflour, honey and chilli in a small saucepan. Simmer 1–2 minutes until thickened.','Toss prawns and vegetables with sauce and peanuts. Heat rice according to its packet and divide between two bowls; finish with spring onion greens.'],internal=63,allergens=['crustacean','peanut','soy','sesame','wheat','gluten'],equipment=['Small saucepan'],nutritionNote='Source estimate includes 250 g precooked microwave rice shared between two portions; this is not dry rice.')
add('air-fryer-buffalo-wings','Buffalo wings with yoghurt ranch',C,3,200,10,30,[[1000,'g','chicken wings','Approximately 12 whole wings'],[.5,'tsp','baking powder'],[15,'ml','cornflour'],[1.25,'tsp','garlic granules','1 tsp coating; 0.25 tsp dip'],[1,'tsp','smoked paprika'],[.5,'tsp','cayenne'],[15,'ml','vegetable oil'],[25,'g','butter'],[15,'ml','hot sauce'],[.5,'tsp','honey'],[60,'ml','mayonnaise'],[60,'ml','natural yoghurt'],[.5,'tsp','lemon juice']],['Dry wings well. Mix baking powder, cornflour, 1 tsp garlic, paprika and cayenne. Toss wings with oil and this coating.','Air fry in one layer at 200°C for 25–30 minutes, turning halfway; add time for extra batches. Check 74°C at the thickest joints.','Melt butter with hot sauce and honey. Mix mayonnaise, yoghurt, remaining garlic and lemon separately for ranch.','Toss cooked wings in the warm buffalo sauce and serve the ranch alongside.'],allergens=['milk','egg','sulphites'],portion='One third of the bone-in wing batch with one third of each sauce.',nutritionNote='Source estimate includes all buffalo sauce and ranch; source allows sour cream or yoghurt, and this selects yoghurt. Bone-in weight differs from edible yield.')
add('sticky-air-fryer-salmon-rice-bowl','Sticky salmon with edamame and cucumber',S,4,175,15,7,[[500,'g','skinless salmon','Cut into 2 cm cubes'],[45,'ml','soy sauce','30 ml marinade; 15 ml radishes'],[15,'g','ginger','Grated'],[30,'ml','honey'],[15,'ml','sesame oil'],[30,'ml','sriracha'],[30,'ml','sesame seeds','Half marinade; half salad'],[150,'g','edamame beans','Shelled','frozen'],[15,'ml','apple cider vinegar'],[1,'tsp','caster sugar'],[.5,'each','cucumber','Thinly sliced'],[200,'g','radishes','Sliced'],[15,'g','pickled ginger'],[4,'each','nori sheets']],['Marinate salmon for 10 minutes in 30 ml soy, ginger, honey, sesame oil, sriracha and half the sesame seeds.','Spread salmon and marinade in a shallow approved pan. Air fry at 175°C for 5–7 minutes, turning once, until each large cube reaches 63°C.','Cook edamame according to its packet. Combine with cucumber, vinegar, sugar and remaining sesame seeds. Toss radishes with remaining soy.','Divide salmon and salads between four bowls, then add pickled ginger and crumbled nori. Brown rice may be added separately and is not included in the estimate.'],preheat=3,wait=10,allergens=['fish','soy','sesame','wheat','gluten','sulphites'],equipment=['Air-fryer-safe shallow pan'],nutritionNote='Publisher source lists unmeasured cooked rice to serve; the 418 kcal estimate appears to exclude rice (18 g carbohydrate). This version explicitly excludes rice and labels the bowl contents only.')
